        if num == 0:
            return 0
        neg = num < 0
        s = sorted(str(abs(num)))
        if neg:
            return -int(''.join(reversed(s)))
        i = 0
        while s[i] == '0':
            i += 1
        s[0], s[i] = s[i], s[0]
        return int(''.join(s))

