class Solution {
    public long smallestNumber(long num) {
        if (num == 0) return 0;
        boolean neg = num < 0;
        char[] s = Long.toString(Math.abs(num)).toCharArray();
        Arrays.sort(s);
        if (neg) {
            for (int l = 0, r = s.length - 1; l < r; l++, r--) {
                char t = s[l]; s[l] = s[r]; s[r] = t;
            }
            return -Long.parseLong(new String(s));
        }
        int i = 0;
        while (s[i] == '0') i++;
        char t = s[0]; s[0] = s[i]; s[i] = t;
        return Long.parseLong(new String(s));
    }
}

