            return 0
        neg = num < 0
        cnt = [0] * 10
        for ch in str(abs(num)):
            cnt[int(ch)] += 1
        digits = []
        rng = range(10) if not neg else range(9, -1, -1)
        for d in rng:
            digits.extend([str(d)] * cnt[d])
        if not neg and digits[0] == '0':
            i = next(i for i, d in enumerate(digits) if d != '0')
            digits[0], digits[i] = digits[i], digits[0]
        v = int(''.join(digits))
        return -v if neg else v

