public:
    long long smallestNumber(long long num) {
        if (num == 0) return 0;
        bool neg = num < 0;
        int cnt[10] = {0};
        string s = to_string(llabs(num));
        for (char c : s) cnt[c - '0']++;
        string out;
        if (neg) for (int d = 9; d >= 0; d--) out += string(cnt[d], '0' + d);
        else for (int d = 0; d <= 9; d++) out += string(cnt[d], '0' + d);
        if (!neg && out[0] == '0') {
            int i = out.find_first_not_of('0');
            swap(out[0], out[i]);
        }
        long long v = stoll(out);
        return neg ? -v : v;
    }
};

