class Solution {
    public long smallestNumber(long num) {
        if (num == 0) return 0;
        boolean neg = num < 0;
        int[] cnt = new int[10];
        for (char c : Long.toString(Math.abs(num)).toCharArray()) cnt[c - '0']++;
        StringBuilder sb = new StringBuilder();
        if (neg) for (int d = 9; d >= 0; d--) for (int k = 0; k < cnt[d]; k++) sb.append((char) ('0' + d));
        else for (int d = 0; d <= 9; d++) for (int k = 0; k < cnt[d]; k++) sb.append((char) ('0' + d));
        String out = sb.toString();
        if (!neg && out.charAt(0) == '0') {
            int i = 0;
            while (out.charAt(i) == '0') i++;
            char[] a = out.toCharArray();
            char t = a[0]; a[0] = a[i]; a[i] = t;
            out = new String(a);
        }
        long v = Long.parseLong(out);
        return neg ? -v : v;
    }
}

